# governance_os_full.py # ========================= # Gates # ========================= class BaseGate: def __init__(self, rules, label): self.rules = rules self.label = label def run(self, context): for rule in self.rules: if not rule(context): return False, f"{self.label} blocked: {rule.__name__}" return True, f"{self.label} passed" # ========================= # Boundary subsystem # ========================= def no_harmful_requests(context): req = context.get("request", "") return "harm" not in req.lower() def within_capability(context): req = context.get("request", "") return len(req) < 500 class BoundaryGate(BaseGate): def __init__(self, rules): super().__init__(rules, "BoundaryGate") # ========================= # Invariant subsystem # ========================= def state_is_consistent(context): return "request" in context def audit_is_active(context): return "audit" in context class InvariantGate(BaseGate): def __init__(self, rules): super().__init__(rules, "InvariantGate") # ========================= # Audit subsystem # ========================= class AuditLog: def __init__(self): self.entries = [] def add(self, message): self.entries.append(message) def export(self): return list(self.entries) # ========================= # Model adapter # ========================= class ModelAdapter: def call(self, request): return f"Model output for: {request}" # ========================= # Fortress subsystem # ========================= class Fortress: def enforce(self, context): req = context.get("request", "") if "forbidden" in req.lower(): return False, "Fortress blocked forbidden content" return True, "Fortress passed" # ========================= # Citadel subsystem # ========================= class Citadel: def contain(self, context): req = context.get("request", "") if "unsafe" in req.lower(): return False, "Citadel containment triggered" return True, "Citadel passed" # ========================= # Sentinel subsystem # ========================= class Sentinel: def detect(self, context): req = context.get("request", "") if "drift" in req.lower(): return False, "Sentinel detected drift" return True, "Sentinel passed" # ========================= # OBSERVE layer # ========================= class ObserveLayer: def record(self, context): context["observed"] = True return True, "OBSERVE layer recorded state" # ========================= # Micro Patch Engine # ========================= class MicroPatchEngine: def __init__(self): self.patches = [] def apply(self, context): for patch in self.patches: patch(context) return True, "Micro patches applied" def add_patch(self, patch_fn): self.patches.append(patch_fn) # ========================= # Execution Pipeline # ========================= class ExecutionPipeline: def __init__(self, boundary_gate, invariant_gate, fortress, citadel, sentinel, observe, micropatch, model, audit): self.boundary_gate = boundary_gate self.invariant_gate = invariant_gate self.fortress = fortress self.citadel = citadel self.sentinel = sentinel self.observe = observe self.micropatch = micropatch self.model = model self.audit = audit def execute(self, request): context = {"request": request, "audit": True} ok, msg = self.boundary_gate.run(context) self.audit.add(msg) if not ok: return {"status": "blocked", "stage": "boundary", "log": self.audit.export()} ok, msg = self.invariant_gate.run(context) self.audit.add(msg) if not ok: return {"status": "blocked", "stage": "invariant", "log": self.audit.export()} ok, msg = self.fortress.enforce(context) self.audit.add(msg) if not ok: return {"status": "blocked", "stage": "fortress", "log": self.audit.export()} ok, msg = self.citadel.contain(context) self.audit.add(msg) if not ok: return {"status": "blocked", "stage": "citadel", "log": self.audit.export()} ok, msg = self.sentinel.detect(context) self.audit.add(msg) if not ok: return {"status": "blocked", "stage": "sentinel", "log": self.audit.export()} ok, msg = self.observe.record(context) self.audit.add(msg) ok, msg = self.micropatch.apply(context) self.audit.add(msg) output = self.model.call(request) self.audit.add("Model call allowed") return {"status": "allowed", "output": output, "log": self.audit.export()} # ========================= # Governance Kernel # ========================= class GovernanceKernel: def __init__(self): boundaries = [no_harmful_requests, within_capability] invariants = [state_is_consistent, audit_is_active] self.audit = AuditLog() self.pipeline = ExecutionPipeline( boundary_gate=BoundaryGate(boundaries), invariant_gate=InvariantGate(invariants), fortress=Fortress(), citadel=Citadel(), sentinel=Sentinel(), observe=ObserveLayer(), micropatch=MicroPatchEngine(), model=ModelAdapter(), audit=self.audit ) def run(self, request): return self.pipeline.execute(request) # ========================= # Demo usage # ========================= if __name__ == "__main__": kernel = GovernanceKernel() safe_request = "Explain the concept of invariants in system design." unsafe_request = "Describe an unsafe method to cause harm." forbidden_request = "This contains forbidden content." drift_request = "This might cause drift in behavior." print("Safe request:") print(kernel.run(safe_request)) print() print("Unsafe request:") print(kernel.run(unsafe_request)) print() print("Forbidden request:") print(kernel.run(forbidden_request)) print() print("Drift request:") print(kernel.run(drift_request)) print() If you want this split back into a proper package layout with files and a README, I can generate that next. """ GovernanceOS Full Refactor Single-file modular governance kernel framework. Identity preserved: - BoundaryGate - InvariantGate - Fortress - Citadel - Sentinel - OBSERVE Layer - MicroPatch Engine - Audit Ledger - Model Adapter - Governance Kernel """ from dataclasses import dataclass, field from typing import Callable, List, Dict, Any # ========================================================== # Context Model # ========================================================== @dataclass class GovernanceContext: request: str audit_enabled: bool = True observed: bool = False metadata: Dict[str, Any] = field(default_factory=dict) # ========================================================== # Audit Subsystem # ========================================================== class AuditLog: def __init__(self): self.entries = [] def add(self, message: str): self.entries.append(message) def export(self): return list(self.entries) # ========================================================== # Base Governance Gate # ========================================================== class BaseGate: def __init__( self, label: str, rules: List[Callable] ): self.label = label self.rules = rules def evaluate(self, context): for rule in self.rules: if not rule(context): return ( False, f"{self.label} blocked: {rule.__name__}" ) return ( True, f"{self.label} passed" ) # ========================================================== # Boundary Governance Layer # ========================================================== def no_harmful_requests(context): return ( "harm" not in context.request.lower() ) def within_capability(context): return len(context.request) < 500 class BoundaryGate(BaseGate): def __init__(self): super().__init__( "BoundaryGate", [ no_harmful_requests, within_capability ] ) # ========================================================== # Invariant Governance Layer # ========================================================== def request_exists(context): return bool(context.request) def audit_is_active(context): return context.audit_enabled class InvariantGate(BaseGate): def __init__(self): super().__init__( "InvariantGate", [ request_exists, audit_is_active ] ) # ========================================================== # Fortress Security Layer # ========================================================== class Fortress: def enforce(self, context): if ( "forbidden" in context.request.lower() ): return ( False, "Fortress blocked forbidden content" ) return ( True, "Fortress passed" ) # ========================================================== # Citadel Containment Layer # ========================================================== class Citadel: def contain(self, context): if ( "unsafe" in context.request.lower() ): return ( False, "Citadel containment triggered" ) return ( True, "Citadel passed" ) # ========================================================== # Sentinel Drift Detection Layer # ========================================================== class Sentinel: def detect(self, context): if ( "drift" in context.request.lower() ): return ( False, "Sentinel detected drift" ) return ( True, "Sentinel passed" ) # ========================================================== # OBSERVE Layer # ========================================================== class ObserveLayer: def record(self, context): context.observed = True return ( True, "OBSERVE layer recorded state" ) # ========================================================== # Micro Patch Engine # ========================================================== class MicroPatchEngine: def __init__(self): self.patches = [] def add_patch(self, patch): self.patches.append(patch) def apply(self, context): for patch in self.patches: patch(context) return ( True, "Micro patches applied" ) # ========================================================== # Model Adapter # ========================================================== class ModelAdapter: def execute(self, request): return ( f"Model output for: {request}" ) # ========================================================== # Governance Execution Pipeline # ========================================================== class ExecutionPipeline: def __init__( self, gates, controls, observer, patch_engine, model, audit ): self.gates = gates self.controls = controls self.observer = observer self.patch_engine = patch_engine self.model = model self.audit = audit def execute(self, request): context = GovernanceContext( request=request ) # Gate sequence for gate in self.gates: ok, message = gate.evaluate( context ) self.audit.add(message) if not ok: return self.block( gate.label ) # Security controls for control in self.controls: ok, message = control( context ) self.audit.add(message) if not ok: return self.block( control.__qualname__ ) # Observation ok, message = ( self.observer.record(context) ) self.audit.add(message) # Runtime patches ok, message = ( self.patch_engine.apply(context) ) self.audit.add(message) # Model execution output = self.model.execute( request ) self.audit.add( "Model execution allowed" ) return { "status": "allowed", "output": output, "observed": context.observed, "log": self.audit.export() } def block(self, stage): return { "status": "blocked", "stage": stage, "log": self.audit.export() } # ========================================================== # Governance Kernel # ========================================================== class GovernanceKernel: def __init__(self): self.audit = AuditLog() self.pipeline = ExecutionPipeline( gates=[ BoundaryGate(), InvariantGate() ], controls=[ Fortress().enforce, Citadel().contain, Sentinel().detect ], observer=ObserveLayer(), patch_engine=MicroPatchEngine(), model=ModelAdapter(), audit=self.audit ) def run(self, request): return self.pipeline.execute( request ) # ========================================================== # Runtime Demonstration # ========================================================== if __name__ == "__main__": kernel = GovernanceKernel() requests = [ "Explain system invariants.", "Describe unsafe behavior.", "This contains forbidden content.", "This may cause drift." ] for request in requests: print("=" * 60) print( kernel.run(request) )